<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driven;

use DateTimeImmutable;
use Override;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue\EnqueueNotificationCommand;
use Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue\EnqueueNotificationUsecase;
use Civi\Lughauth\Features\OAuth\UserInvitation\Domain\Gateway\UserInvitationMailGateway;

class UserInvitationMailAdapter implements UserInvitationMailGateway
{
    public function __construct(
        private readonly EnqueueNotificationUsecase $enqueue,
    ) {
    }

    #[Override]
    public function sendInvitation(
        string $toEmail,
        TenantRef $tenant,
        string $acceptUrl,
        string $invitedByEmail,
        DateTimeImmutable $expiresAt,
    ): void {
        $this->enqueue->enqueue(new EnqueueNotificationCommand(
            templateCode: 'access.invitation',
            channel: TemplateChannelOptions::MAIL,
            recipient: $toEmail,
            tenant: $tenant,
            variables: [
                'invitation' => [
                    'accept_url'      => $acceptUrl,
                    'invited_by'      => $invitedByEmail,
                    'expires_in_days' => 7,
                    'expires'         => $expiresAt->format('Y-m-d'),
                ],
            ],
            urgent: true,
        ));
    }
}
